async function handleReqFile(file){toast('Lendo requisição…');try{const lib=await loadPDFJS();const buf=await file.arrayBuffer();const pdf=await lib.getDocument({data:buf}).promise;let text='';
  for(let i=1;i<=pdf.numPages;i++){const pg=await pdf.getPage(i);const tc=await pg.getTextContent();const rows={};tc.items.forEach(it=>{const y=Math.round((it.transform&&it.transform[5])||0);(rows[y]=rows[y]||[]).push({x:(it.transform&&it.transform[4])||0,s:it.str});});Object.keys(rows).map(Number).sort((a,b)=>b-a).forEach(y=>{const line=rows[y].sort((a,b)=>a.x-b.x).map(o=>o.s).join(' ').replace(/\s+/g,' ').trim();if(line)text+=line+'\n';});}
  addReqFromParsed(parseRequisicao(text));
 }catch(e){console.error(e);toast('Falha ao ler o PDF (precisa de internet p/ carregar o leitor).',false);}}
function addReqFromParsed(p){if(!p.items.length){toast('Não achei itens na requisição. Confira o PDF.',false);return;}
 const ex=p.num?REQS.find(r=>r.num===p.num):null;
 if(ex){openReqs[ex.id]=true;ex.status='aberta';saveReqs();renderReqList();toast('Requisição '+p.num+' já estava na lista — reaberta',false);return;}
 const items=p.items.map(it=>({cod:it.cod,mat:it.mat,maq:it.maq,qtd:reqNum(it.qtd),un:it.un||'KG',delivered:0,done:false,picks:[]}));
 const r={id:uid(),num:p.num||('REQ-'+Date.now()),status:'aberta',prio:p.prio,turno:p.turno,solic:p.solic,data:p.data,hora:p.hora,setor:p.setor,createdAt:nowISO(),items};
 REQS.unshift(r);saveReqs();openReqs[r.id]=true;curReqId=r.id;renderReqList();
 toast('Requisição '+r.num+' importada · '+items.length+' item(ns)');}

function toggleReq(id){openReqs[id]=!openReqs[id];renderReqList();}
function closeReq(id){const r=REQS.find(x=>x.id===id);if(!r)return;r.status='fechada';saveReqs();renderReqList();toast('Requisição '+r.num+' fechada');}
function reopenReq(id){const r=REQS.find(x=>x.id===id);if(!r)return;r.status='aberta';openReqs[id]=true;saveReqs();renderReqList();}
function delReq(id){const r=REQS.find(x=>x.id===id);if(!r)return;if(!confirm('Remover a requisição '+r.num+' da lista?'))return;REQS=REQS.filter(x=>x.id!==id);if(curReqId===id){curReqId=null;curItemIdx=-1;const pl=$('#pkPlan');if(pl)pl.innerHTML='<p style="color:var(--muted);font-size:.85rem">Gere um plano para ver as retiradas sugeridas.</p>';}saveReqs();renderReqList();}

function reqCardHTML(r){const exp=!!openReqs[r.id];const allDone=r.items.length>0&&r.items.every(it=>it.done);const pr=da(r.prio||'');const priCls=pr.includes('critic')?'pri-crit':(pr.includes('alt')?'pri-alta':'');const prPill=(pr.includes('critic')||pr.includes('alt'))?'out':'muted';const closed=r.status==='fechada';const doneCount=r.items.filter(it=>it.done).length;
 const head='<div class="rqh" onclick="toggleReq(\''+r.id+'\')"><span class="chev">'+(exp?'\u25be':'\u25b8')+'</span><span class="num">'+r.num+'</span>'+(r.prio?'<span class="pill '+prPill+'">'+r.prio+'</span>':'')+(r.turno?'<span class="pill muted">'+r.turno+'</span>':'')+'<span class="spx"></span><span class="pill '+(allDone?'in':'muted')+'">'+doneCount+'/'+r.items.length+' itens</span>'+(closed?'<span class="pill muted">fechada</span>':'')+'</div>';
 if(!exp)return '<div class="sep-req '+priCls+(closed?' closed':'')+'">'+head+'</div>';
 const meta='<div class="meta">'+[r.setor?'Setor: <b>'+r.setor+'</b>':'',r.solic?'Solic.: <b>'+r.solic+'</b>':'',r.data?('<b>'+r.data+(r.hora?' '+r.hora:'')+'</b>'):''].filter(Boolean).map(s=>'<span>'+s+'</span>').join('')+'</div>';
 const items=r.items.map((it,i)=>{const pct=it.qtd>0?Math.max(0,Math.min(100,Math.round((it.delivered||0)/it.qtd*100))):0;return '<div class="sep-item'+(it.done?' done':'')+'"><div class="ix">'+(it.done?'\u2713':(i+1))+'</div><div class="body"><div class="t">'+it.cod+' · '+it.mat+'</div><div class="d"><span class="sep-chip">\u2192 '+it.maq+'</span><span>pedido <b>'+fmt(it.qtd)+' '+String(it.un||'').toLowerCase()+'</b></span><span>entregue <b>'+fmt(it.delivered||0)+' kg</b></span></div>'+(it.done?'':'<div class="sep-prog"><i style="width:'+pct+'%"></i></div>')+'</div>'+(it.done?'<span class="pill in">ok</span>':'<button class="btn brand" style="padding:8px 15px;font-size:.78rem;white-space:nowrap" onclick="attendItem(\''+r.id+'\','+i+')">Atender</button>')+'</div>';}).join('');
 const actions='<div class="sep-acts">'+(closed?('<button class="gbtn" onclick="reopenReq(\''+r.id+'\')">Reabrir</button>'):('<button class="gbtn" onclick="closeReq(\''+r.id+'\')">'+(allDone?'\u2713 Concluir':'Fechar')+'</button>'))+'<button class="gbtn danger" onclick="delReq(\''+r.id+'\')">Remover</button></div>';
 return '<div class="sep-req '+priCls+(closed?' closed':'')+'">'+head+meta+items+actions+'</div>';}
function renderReqList(){const host=document.getElementById('reqCard');if(!host)return;if(!REQS.length){host.innerHTML='';return;}
 const open=REQS.filter(r=>r.status!=='fechada'),closed=REQS.filter(r=>r.status==='fechada');
 host.innerHTML='<div class="sep-list"><div class="sep-sec">Requisições abertas <span class="n">'+open.length+'</span></div>'+(open.length?open.map(reqCardHTML).join(''):'<p class="sep-emptytxt">Nenhuma aberta no momento.</p>')+(closed.length?('<div class="sep-sec">Fechadas <span class="n">'+closed.length+'</span></div>'+closed.map(reqCardHTML).join('')):'')+'</div>';}
