function attendItem(reqId,idx){const r=REQS.find(x=>x.id===reqId);if(!r)return;const it=r.items[idx];if(!it)return;curReqId=reqId;curItemIdx=idx;pickDest=it.maq;
 const prod=norm(it.cod);const needed=Math.max(0,(it.qtd||0)-(it.delivered||0));const pos=pickPositions(prod);let acc=0,alloc=[];for(const p of pos){if(acc>=needed&&alloc.length)break;alloc.push({id:p.id,code:code(p),q:p.q});acc+=p.q;}
 renderAttendPlan(r,idx,alloc,acc);const pl=document.getElementById('pkPlan');if(pl&&pl.scrollIntoView)pl.scrollIntoView({behavior:'smooth',block:'center'});}
function renderAttendPlan(r,idx,alloc,acc){const it=r.items[idx];const el=$('#pkPlan');if(!el)return;const CK=(typeof ICONS!=="undefined"&&(ICONS.ok||ICONS.check))?(ICONS.ok||ICONS.check):'\u2713';
 const banner='<div class="sep-banner"><div class="bi">\u2192</div><div><div class="bk">Levar para a máquina</div><div class="bv">'+it.maq+'</div></div>'+(r.num?'<div class="brq"><div class="k">Requisição</div><div class="v">'+r.num+'</div></div>':'')+'</div>';
 if(it.done){el.innerHTML=banner+'<div class="empty" style="padding:34px"><div class="ei" style="color:var(--in)">'+CK+'</div><b>Item concluído</b><div>'+it.cod+' · entregue '+fmt(it.delivered)+' kg para '+it.maq+'.</div></div>';return;}
 if(!alloc.length){el.innerHTML=banner+'<div class="empty" style="padding:34px"><div class="ei">'+ICONS.box+'</div><b>Sem estoque</b><div>Nenhuma posição com '+it.cod+'.</div></div>';return;}
 const stats='<div class="sep-stats"><div class="sep-stat"><div class="k">Pedido</div><div class="v">'+fmt(it.qtd)+' '+String(it.un||'').toLowerCase()+'</div></div><div class="sep-stat ok"><div class="k">Entregue</div><div class="v">'+fmt(it.delivered||0)+' kg</div></div><div class="sep-stat br"><div class="k">Vagas</div><div class="v">'+alloc.length+'</div></div></div>';
 el.innerHTML=banner+stats+'<div class="sep-hint">Vá até a vaga, toque <b>Bipar</b>, leia o <b>endereço</b> e a <b>etiqueta</b> da bobina e confirme. Cada confirmação dá baixa e soma no pedido.</div>'
  +alloc.map((a,i)=>'<div class="sep-pos" id="pos-'+a.id+'"><div class="px">'+(i+1)+'</div><div class="pb"><div class="c">'+a.code+'</div><div class="q">tem '+fmt(a.q)+' kg</div></div><button class="btn brand" style="padding:8px 15px;font-size:.78rem" onclick="togglePickScan(\''+a.id+'\',\''+a.code+'\')">Bipar</button></div>'
    +'<div id="scan-'+a.id+'" class="sep-scan" style="display:none"><div class="sep-scan-g"><label class="fld" style="margin:0"><span class="lab">Endereço</span><input class="input code" id="addr-'+a.id+'" value="'+a.code+'" autocomplete="off"></label><label class="fld" style="margin:0"><span class="lab">Etiqueta da bobina</span><input class="input code" id="et-'+a.id+'" placeholder="bipe a etiqueta" autocomplete="off"></label></div><button class="btn sep-confirm" onclick="confirmPick(\''+a.id+'\',\''+a.code+'\')">Confirmar saída</button></div>').join('')
  +'<button class="gbtn sep-print" onclick="printSepGuiaReq(\''+r.id+'\','+idx+')">'+((typeof ICONS!=="undefined"&&ICONS.print)?ICONS.print:'')+' Imprimir guia</button>';}
function togglePickScan(id,code){const d=document.getElementById('scan-'+id);if(!d)return;const show=d.style.display==='none';d.style.display=show?'block':'none';if(show){const e=document.getElementById('et-'+id);if(e){if(!e._wired){e._wired=1;e.addEventListener('keydown',function(ev){if(ev.key==='Enter'){ev.preventDefault();confirmPick(id,code);}});}e.focus();}}}
function confirmPick(posId,codeStr){const r=REQS.find(x=>x.id===curReqId);if(!r){toast('Selecione um item da requisição',false);return;}const it=r.items[curItemIdx];if(!it)return;
 const addrEl=document.getElementById('addr-'+posId),etEl=document.getElementById('et-'+posId);const addr=addrEl?String(addrEl.value||'').trim():'';const et=etEl?String(etEl.value||'').trim().toUpperCase():'';
 if(addr&&norm(addr)!==norm(codeStr)){toast('Endereço bipado ('+addr+') não confere com '+codeStr,false);return;}
 const sp=S.find(x=>x.id===posId);if(!sp){toast('Posição não encontrada',false);return;}
 let take;
 if(et){if(!BOB[et]){toast('Etiqueta '+et+' não está no catálogo',false);return;}if(LOC[et]&&norm(LOC[et])!==norm(codeStr)){toast('Etiqueta '+et+' está em '+LOC[et]+', não em '+codeStr,false);return;}if(BOB[et].pr&&norm(BOB[et].pr)!==norm(it.cod)){toast('Etiqueta é do produto '+BOB[et].pr+', não '+it.cod,false);return;}take=Math.min(sp.q,Number(BOB[et].pl)||sp.q);}
 else{take=sp.q;}
 if(take<=0){toast('Sem saldo nessa posição',false);return;}
 const before=sp.q;sp.q=Math.max(0,before-take);
 if(et){delete LOC[et];if(BOB[et])BOB[et].rem=0;}
 if(sp.q<=0){sp.q=0;sp.o=false;sp.pr='';Object.keys(LOC).forEach(k=>{if(norm(LOC[k])===norm(codeStr)){delete LOC[k];if(BOB[k])BOB[k].rem=0;}});}
 sp.upd=nowISO();sp.by=session.u;
 MV.unshift({id:uid(),action:'saida',w:cfg.warehouse,code:codeStr,pr:it.cod,q:take,u:(typeof unitOf==='function'?unitOf(it.cod):'KG'),before,after:sp.o?sp.q:0,at:nowISO(),by:session.u,dest:it.maq||'',req:r.num});
 try{if(typeof syncMov==='function')syncMov(MV[0]);}catch(e){}
 try{enqueue3dTask(codeStr,'out');}catch(e){}
 it.delivered=(it.delivered||0)+take;it.picks=it.picks||[];it.picks.push({posId,code:codeStr,et:et||'',q:take,at:nowISO(),by:session.u});
 if(it.delivered>=it.qtd)it.done=true;
 saveLOC();saveBOB();saveReqs();persist();
 try{if(typeof supa!=='undefined'&&supa&&typeof chunkUp==='function'&&typeof spRow==='function')chunkUp('espacos',S.map(spRow));}catch(e){}
 try{if(typeof syncBobAll==='function')syncBobAll();}catch(e){}
 logAct('separacao',it.cod+' \u2212'+fmt(take)+'kg '+codeStr+(it.maq?(' \u2192 '+it.maq):'')+' ['+r.num+']');
 toast('Saída confirmada: '+fmt(take)+' kg de '+codeStr+(et?(' · '+et):''));
 renderReqList();
 attendItem(curReqId,curItemIdx);
 if(!it.done){setTimeout(function(){const sp2=S.find(x=>x.id===posId);if(sp2&&sp2.q>0)togglePickScan(posId,codeStr);},40);}
 else{const all=r.items.every(x=>x.done);if(all)toast('Todos os itens da '+r.num+' concluídos — pode fechar a requisição',true);}}

