function loadXLSX(){return window.XLSX?Promise.resolve():new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';s.onload=res;s.onerror=()=>rej(new Error('cdn'));document.head.appendChild(s);});}
function da(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();}
function colFind(H){const names=[].slice.call(arguments,1);for(let i=0;i<H.length;i++){const h=da(H[i]);for(const n of names)if(h.includes(n))return i;}return -1;}
function colFindP(H){const names=[].slice.call(arguments,1);for(const n of names){for(let i=0;i<H.length;i++){if(da(H[i]).includes(n))return i;}}return -1;}
function colPeso(H){
 // normaliza removendo pontos/espaços extras: "Qtd. Prod." -> "qtd prod"
 const nz=s=>da(s).replace(/[._\s]+/g,' ').trim();
 // 1) prioridade: coluna de QUANTIDADE PRODUZIDA (a verde), incluindo abreviações
 const prod=['quantidade produzida','qtd produzida','quant produzida','qtd prod','quant prod','produzida'];
 for(const t of prod){for(let i=0;i<H.length;i++){if(nz(H[i]).includes(t))return i;}}
 // 2) só se não houver coluna de produzida, usa peso líquido como reserva
 return colFindP(H,'liquido','peso liq','liq');
}
function ingestRows(rows){let hi=-1;for(let i=0;i<Math.min(rows.length,15);i++){const r=(rows[i]||[]).map(x=>String(x||'').toLowerCase());if(r.some(c=>c.includes('etiqueta'))&&r.some(c=>c.includes('produto'))){hi=i;break;}}
 if(hi<0){toast('Não achei colunas Etiqueta/Produto',false);return 0;}
 const H=rows[hi],ie=colFind(H,'etiqueta'),ip=colFind(H,'produto'),idd=colFind(H,'descri'),iq=colPeso(H);
 if(ie<0||ip<0){toast('Cabeçalho incompleto',false);return 0;}
 if(iq<0)toast('Atenção: coluna Quantidade Produzida não encontrada',false);
 let n=0;var _apAt=nowISO(),_apBy=(typeof session!=='undefined'&&session?session.u:'');for(let i=hi+1;i<rows.length;i++){const r=rows[i]||[];const et=String(r[ie]||'').trim().toUpperCase();const pr=String(r[ip]||'').trim();if(!et||!pr)continue;BOB[et]={pr,desc:idd>-1?String(r[idd]||'').trim():'',pl:iq>-1?brNum(r[iq]):0,apAt:_apAt,apBy:_apBy};n++;}
 saveBOB();return n;}
let impRows=null;
function detectHeader(rows){for(let i=0;i<Math.min(rows.length,20);i++){const r=(rows[i]||[]).map(x=>da(x));if(r.some(c=>c.includes('etiqueta'))&&r.some(c=>c.includes('produto')))return i;}return 0;}
function handleImport(file){const ext=(file.name.split('.').pop()||'').toLowerCase();$('#impStatus').innerHTML='<p style="color:var(--muted);font-size:.82rem;margin:10px 0 0">Lendo '+file.name+'…</p>';
 const done=rows=>{impRows=rows;$('#impStatus').innerHTML='';renderMapping();};
 if(ext==='csv'){const r=new FileReader();r.onload=()=>{const txt=r.result;const head=txt.split(/\r?\n/)[0]||'';const delim=(head.split(';').length>head.split(',').length)?';':',';const rows=txt.split(/\r?\n/).map(l=>l.split(delim).map(c=>c.replace(/^"|"$/g,'')));done(rows);};r.readAsText(file);}
 else{loadXLSX().then(()=>{const r=new FileReader();r.onload=()=>{try{const wb=XLSX.read(new Uint8Array(r.result),{type:'array'});const sn=wb.SheetNames.find(s=>/apont/i.test(s))||wb.SheetNames[wb.SheetNames.length-1];done(XLSX.utils.sheet_to_json(wb.Sheets[sn],{header:1,raw:true,defval:''}));}catch(e){toast('Erro ao ler o arquivo',false);}};r.readAsArrayBuffer(file);}).catch(()=>toast('Sem internet p/ ler .xlsx — exporte como CSV',false));}}
function renderMapping(){const rows=impRows;if(!rows||!rows.length)return;
 const hrEl=$('#impHrow');let hi=(hrEl&&hrEl.value)?Math.max(0,parseInt(hrEl.value,10)-1):detectHeader(rows);
 const H=rows[hi]||[];
 const sel=(id,g)=>'<select class="input" id="'+id+'">'+H.map((h,i)=>'<option value="'+i+'" '+(i===g?'selected':'')+'>'+(String(h||'').trim()||('Coluna '+(i+1)))+'</option>').join('')+'</select>';
 const gE=colFind(H,'etiqueta'),gP=colFind(H,'produto'),gD=colFind(H,'descri'),gQ=colPeso(H);
 $('#impMap').innerHTML='<div class="panel" style="max-width:700px;margin-top:16px"><div class="ph"><span class="pdot"></span>Conferir colunas antes de importar</div>'+
  '<label class="fld"><span class="lab">Linha do cabeçalho</span><input class="input" id="impHrow" type="number" min="1" value="'+(hi+1)+'" style="max-width:130px"></label>'+
  '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:6px">'+
   '<label class="fld"><span class="lab">Etiqueta</span>'+sel('mapEt',gE)+'</label>'+
   '<label class="fld"><span class="lab">Produto (0303…)</span>'+sel('mapPr',gP)+'</label>'+
   '<label class="fld"><span class="lab">Descrição</span>'+sel('mapDe',gD)+'</label>'+
   '<label class="fld"><span class="lab">Peso (Qtd. Produzida)</span>'+sel('mapPl',gQ)+'</label>'+
  '</div>'+
  '<div class="lab" style="margin-bottom:6px">Pré-visualização</div><div id="mapPrev" style="font-family:var(--mono);font-size:.76rem;color:var(--muted);background:var(--card-2);border:1px solid var(--line);border-radius:10px;padding:11px 13px;margin-bottom:14px;line-height:1.7"></div>'+
  '<button class="btn brand" id="mapDo" style="width:100%;height:48px">Importar com estas colunas</button></div>';
 $('#impHrow').onchange=renderMapping;['mapEt','mapPr','mapDe','mapPl'].forEach(id=>$('#'+id).onchange=mapPreview);$('#mapDo').onclick=doImport;mapPreview();}
function mapPreview(){const rows=impRows,hi=Math.max(0,parseInt($('#impHrow').value,10)-1),ie=+$('#mapEt').value,ip=+$('#mapPr').value,idd=+$('#mapDe').value,iq=+$('#mapPl').value;let html='',c=0;for(let i=hi+1;i<rows.length&&c<4;i++){const r=rows[i]||[];if(!String(r[ie]||'').trim())continue;html+='<div>'+String(r[ie]||'')+' · '+String(r[ip]||'')+' · '+String(r[idd]||'').slice(0,22)+' · <b style="color:var(--in)">'+fmt(brNum(r[iq]))+' kg</b></div>';c++;}$('#mapPrev').innerHTML=html||'<div>sem linhas de exemplo</div>';}
