(function(){const navMov=[...document.querySelectorAll('.nav')].find(n=>n.dataset.view==='v-mov');if(navMov){const nv=document.createElement('div');nv.className='nav';nv.dataset.view='v-recv';nv.dataset.ic='inbox';nv.innerHTML='<span class="ni"></span>Gestão de Recebimento';navMov.parentNode.insertBefore(nv,navMov);nv.onclick=()=>go('v-recv');}const sec=document.createElement('section');sec.className='view';sec.id='v-recv';document.querySelector('main').appendChild(sec);TITLES['v-recv']='Gestão de Recebimento';const _rv=render;render=function(id){if(id==='v-recv')return renderRecv();return _rv(id);};})();
