          +'<div style="color:var(--ink);font-size:.9rem;margin-top:6px;font-weight:500">'+(g.desc||'—')+'</div>'
          +'<div style="color:var(--faint);font-size:.72rem;margin-top:5px">último bipe '+rel(g.at)+'</div>'
        +'</div>'
        +'<div style="text-align:right;white-space:nowrap"><div style="font-family:var(--disp);font-weight:800;font-size:1.6rem;line-height:1">'+fmt(_kgR)+' <span style="font-size:.8rem;color:var(--muted);font-weight:600">kg</span></div></div>'
      +'</div>'
