      +((typeof isStrictAdmin==='function'&&isStrictAdmin())?'<div style="display:flex;gap:10px;margin-top:12px"><button class="gbtn" data-rmcode="'+g.pr+'" style="margin-left:auto;color:var(--out)">Zerar código</button></div>':'')
