/* ===== TELAS OCULTAS DA NAVEGAÇÃO =====
   Movimentação, Separação, Baixa Protheus e Transferências saem do
   menu a pedido. As telas e o código continuam no sistema (nada foi apagado) —
   pra reativar qualquer uma, é só tirar a view da lista abaixo. Uso .remove()
   em vez de display:none porque o applyPerms() reexibe navs permitidas ao logar,
   o que desfaria um esconder por estilo. */
(function(){
  try{
    var ocultas=['v-mov','v-pick','v-protheus','v-transf'];
    ocultas.forEach(function(v){
      document.querySelectorAll('.nav[data-view="'+v+'"]').forEach(function(n){n.remove();});
    });
    /* Ctrl+K monta a lista pela NAVITEMS — sem esta limpeza, as telas ocultas
       continuariam acessíveis pela busca de comandos */
    try{if(typeof NAVITEMS!=='undefined'&&Array.isArray(NAVITEMS)){
      for(var i=NAVITEMS.length-1;i>=0;i--){if(ocultas.indexOf(NAVITEMS[i][0])>=0)NAVITEMS.splice(i,1);}
    }}catch(e){}
  }catch(e){}
})();

/* ===== MAPA: CONFIRMAR NA VAGA E PONTO FINAL =====
   Bug relatado: ao bipar endereço + bobina no mapa, aparecia a tela de imprimir a
   etiqueta do item. Nenhum caminho do boardQuickMove chama impressão diretamente —
   o gatilho é indireto (ex.: leitor de código de barras "teclado" despejando as
   linhas extras do QR multi-linha em outro campo logo depois do confirmar, e isso
   acionando um fluxo de etiqueta). Como a origem é externa ao fluxo, o conserto é
   um ESCUDO: por 2,5s após o confirmar do mapa, qualquer popup de etiqueta
   (drawer "Etiqueta…", seletor de formato, folha de bobina) é suprimido.
   Fora do mapa nada muda — imprimir etiqueta manualmente continua igual. */
(function(){
  if(typeof window.boardQuickMove!=='function'&&typeof boardQuickMove!=='function')return;
  window.__bqSilenceAte=0;
  var _silencio=function(){return Date.now()<(window.__bqSilenceAte||0);};

  /* liga o escudo no início de cada quick move do mapa */
  try{
    var _orig=boardQuickMove;
    boardQuickMove=async function(mode,a,e){
      window.__bqSilenceAte=Date.now()+2500;
      try{return await _orig(mode,a,e);}
      finally{window.__bqSilenceAte=Date.now()+2500;} /* renova: o popup vinha DEPOIS do commit */
    };
    window.boardQuickMove=boardQuickMove;
  }catch(e){}

  /* barreiras nos pontos que abrem UI de etiqueta */
  try{if(typeof askLabelFormat==='function'){var _alf=askLabelFormat;
    askLabelFormat=function(t,cb){if(_silencio())return;return _alf(t,cb);};window.askLabelFormat=askLabelFormat;}}catch(e){}
  try{if(typeof showBobLabel==='function'){var _sbl=showBobLabel;
    showBobLabel=function(et){if(_silencio())return;return _sbl(et);};window.showBobLabel=showBobLabel;}}catch(e){}
  try{if(typeof showLabelSheet==='function'){var _sls=showLabelSheet;
    showLabelSheet=function(c,d,w){if(_silencio())return;return _sls(c,d,w);};window.showLabelSheet=showLabelSheet;}}catch(e){}
  try{if(typeof printIntakeLabelChoose==='function'){var _pil=printIntakeLabelChoose;
    printIntakeLabelChoose=function(it){if(_silencio())return;return _pil(it);};window.printIntakeLabelChoose=printIntakeLabelChoose;}}catch(e){}
  /* rede de segurança: drawer cujo título fala em etiqueta também é barrado no período */
  try{if(typeof openDrawer==='function'){var _od=openDrawer;
    openDrawer=function(titulo,html){
      if(_silencio()&&/etiqueta/i.test(String(titulo||'')))return;
      return _od(titulo,html);
    };window.openDrawer=openDrawer;}}catch(e){}
})();

/* ===== MAPA: ENGOLIR O RABO DO QR (correção de raiz) =====
   Diagnóstico fechado com o usuário: TUDO é bipado, nada digitado. O leitor é do
   tipo "teclado" — digita o que lê, linha a linha, com Enter entre elas — e as
   etiquetas têm QR MULTI-LINHA. Sequência do bug:
     1. leitor digita a linha 1 do QR no campo Bobina;
     2. o Enter da linha 1 dispara o Confirmar (correto);
     3. o leitor CONTINUA digitando as linhas restantes do QR — mas os campos já
        foram limpos, então esse rabo vaza pra fora da barra de bipe e cai em
        outro ponto do sistema, acionando um fluxo de etiqueta/impressão.
   Correção em duas camadas:
     a) TRAVA DE REENTRADA: enquanto um confirmar do mapa está processando, novos
        Enters não disparam outro (o rabo do QR não vira uma segunda movimentação
        com dados pela metade);
     b) BOCA DE LOBO: por 450ms após o confirmar, TODA tecla é engolida na captura
        (documento inteiro) — as linhas restantes do QR morrem antes de chegar a
        qualquer campo, atalho ou palette. 450ms cobre com folga o despejo do
        leitor (~100–200ms) e não atrapalha o próximo bipe legítimo, que nunca
        vem tão rápido após um clique de confirmar.
   O escudo de 2,5s contra popups de etiqueta (bloco acima) fica como cinto de
   segurança extra. */
(function(){
  if(typeof window.boardQuickMove!=='function')return;
  window.__bqSwallowAte=0;
  var _busy=false;
  var _fn=window.boardQuickMove;
  window.boardQuickMove=async function(mode,a,e){
    if(_busy)return;                 /* trava de reentrada */
    _busy=true;
    window.__bqSwallowAte=Date.now()+450;
    try{return await _fn(mode,a,e);}
    finally{
      window.__bqSwallowAte=Date.now()+450; /* renova: o rabo chega DEPOIS do commit */
      setTimeout(function(){_busy=false;},200);
    }
  };
  try{boardQuickMove=window.boardQuickMove;}catch(e){}
  /* boca de lobo: engole todas as teclas do rabo do QR, em fase de captura */
  ['keydown','keypress','keyup'].forEach(function(evt){
    document.addEventListener(evt,function(ev){
      if(Date.now()<(window.__bqSwallowAte||0)){
        ev.stopImmediatePropagation();
        ev.preventDefault();
      }
    },true);
  });
})();

/* ===== TETO DO LOG DE MOVIMENTOS =====
   Auditoria: 7 dos 20 pontos que fazem MV.unshift não aplicavam o corte em 5000.
   Nenhum número errado — mas o log local cresceria sem limite e degradaria o
   aparelho com o tempo. Em vez de caçar cada ponto (e esquecer o próximo que
   alguém criar), o teto vira uma rotina: corta no load e a cada 60s. O histórico
   completo continua na nuvem; os 5000 locais são só o cache de trabalho. */
(function(){
  var teto=function(){}; /* não corta o histórico de movimentações */
  teto();setInterval(teto,60000);
})();

/* ============================================================
   2) VALIDAÇÃO NA PORTA DE ENTRADA
   Os códigos-lixo ("1","123") que poluíam os relatórios entravam pelo bipe sem
   ninguém perceber. O filtro na exibição limpava a tela, mas o dado sujo
   continuava entrando. Agora a validação é na PORTA: produto sem cadastro no
   catálogo pede confirmação explícita antes de entrar na prateleira ou no
   Chão 70. Um "ok" consciente ainda passa (tem material legítimo recém-chegado
   sem cadastro), mas lixo de leitor não entra mais sozinho. */
(function(){
  function temCadastro(pr){
    try{
      pr=String(pr||'').trim().toUpperCase();if(!pr)return false;
      if(typeof VL!=='undefined'&&Array.isArray(VL)&&VL.some(function(v){return String(v.codigo||'').toUpperCase()===pr;}))return true;
      if(typeof descOf==='function'&&descOf(pr))return true;
      if(/^0\d{6,}$/.test(pr))return true; /* formato Packem: aceito mesmo sem descrição */
      return false;
    }catch(e){return true;} /* na dúvida, não bloqueia operação */
  }
  window.prodTemCadastro=temCadastro;
  /* porta 1: entrada na prateleira (cobre mapa, movimentação e armazenar do intermediário) */
  try{
    var _pb=placeBobina;
    placeBobina=function(et,pr,pl,c){
      if(!temCadastro(pr)){
        if(!confirm('O código "'+pr+'" NÃO está no catálogo de produtos.\n\nIsso costuma ser erro de leitura ou etiqueta errada.\nRegistrar a entrada mesmo assim?'))return false;
      }
      return _pb(et,pr,pl,c);
    };
    window.placeBobina=placeBobina;
  }catch(e){}
  /* porta 2: entrada direta no Chão 70 */
  try{
    if(typeof window.floor70Add==='function'){
      var _fa=window.floor70Add;
      window.floor70Add=async function(v){
        try{
          var b=(typeof parseBobina==='function')?parseBobina(v):null;
          var pr=b&&b.pr?String((typeof cleanProd==='function')?cleanProd(b.pr):b.pr):'';
          if(pr&&pr!==String(v).trim().toUpperCase()&&!temCadastro(pr)){
            if(!confirm('O código "'+pr+'" NÃO está no catálogo.\nContar no Chão 70 mesmo assim?'))return;
          }
        }catch(e){}
        return _fa(v);
      };
    }
  }catch(e){}
})();

/* ============================================================
   3) SAÚDE DO SISTEMA — invariantes sobre os DADOS REAIS
   A auditoria estática confere o código; esta tela confere o que o código não
   enxerga: os dados. Cada regra abaixo é algo que NUNCA deveria acontecer num
   armazém saudável — quando acontece, é sintoma de bug de sync ou operação
   errada, e é melhor descobrir aqui do que no inventário. Aba só de admin. */
(function(){
  function _fk(n){try{return (typeof fmt==='function')?fmt(n):n;}catch(e){return n;}}
  function verificar(){
    var problemas=[]; /* {regra, gravidade, itens:[{ref,det}]} */
    var add=function(regra,grav,itens){if(itens.length)problemas.push({regra:regra,grav:grav,itens:itens});};
    var SS=(typeof S!=='undefined'&&Array.isArray(S))?S:[];
    var byCode={};SS.forEach(function(x){try{byCode[code(x)]=x;}catch(e){}});
    /* I1/I2/I3: etiquetas armazenadas (LOC) coerentes com as vagas */
    var i1=[],i2=[],i3=[],i9=[],i8=[];
    if(typeof LOC!=='undefined'){
      Object.keys(LOC).forEach(function(et){
        var addr=LOC[et],sp=byCode[addr];
        if(!sp){i1.push({ref:et,det:'aponta para vaga inexistente '+addr});return;}
        if(!sp.o||(Number(sp.q)||0)<=0)i2.push({ref:et,det:'aponta para '+addr+' que está vazia'});
        var bpr=(typeof BOB!=='undefined'&&BOB[et]&&BOB[et].pr)?BOB[et].pr:null;
        if(bpr&&sp.pr&&bpr!==sp.pr)i3.push({ref:et,det:'produto da etiqueta ('+bpr+') difere do da vaga '+addr+' ('+sp.pr+')'});
        try{if(typeof window.f70HasEt==='function'&&window.f70HasEt(et))i9.push({ref:et,det:'na prateleira ('+addr+') E no Chão 70 ao mesmo tempo'});}catch(e){}
        try{if(typeof STAGE!=='undefined'&&STAGE.some(function(x){return x.et===et;}))i8.push({ref:et,det:'armazenada em '+addr+' mas ainda listada no intermediário'});}catch(e){}
      });
    }
    add('Etiqueta aponta para vaga que não existe','alta',i1);
    add('Etiqueta aponta para vaga vazia','alta',i2);
    add('Produto da etiqueta difere do produto da vaga','alta',i3);
    add('Bobina na prateleira e no Chão 70 ao mesmo tempo','media',i9);
    add('Bobina armazenada mas ainda no intermediário','media',i8);
    /* I4/I5/I6: vagas internamente coerentes */
    var i4=[],i5=[],i6=[];
    SS.forEach(function(x){
      var q=Number(x.q)||0;
      if(x.o&&!x.pr)i4.push({ref:code(x),det:'ocupada sem produto'});
      if(q<0)i5.push({ref:code(x),det:'saldo NEGATIVO: '+_fk(q)+' kg'});
      if(!x.o&&q>0.001)i6.push({ref:code(x),det:'marcada livre com '+_fk(q)+' kg dentro'});
    });
    add('Vaga ocupada sem produto','media',i4);
    add('Saldo negativo','alta',i5);
    add('Vaga "livre" com peso dentro','media',i6);
    /* I7: soma das etiquetas ≠ saldo da vaga (só quando TODAS as etiquetas têm peso) */
    var i7=[];
    if(typeof LOC!=='undefined'&&typeof BOB!=='undefined'){
      var porVaga={};
      Object.keys(LOC).forEach(function(et){(porVaga[LOC[et]]=porVaga[LOC[et]]||[]).push(et);});
      Object.keys(porVaga).forEach(function(addr){
        var sp=byCode[addr];if(!sp||!sp.o)return;
        var ets=porVaga[addr];var soma=0,completo=true;
        ets.forEach(function(et){var b=BOB[et];if(!b||b.pl==null){completo=false;return;}soma+=Number(b.pl)||0;});
        if(completo&&Math.abs(soma-(Number(sp.q)||0))>0.5)
          i7.push({ref:addr,det:'etiquetas somam '+_fk(soma)+' kg, vaga registra '+_fk(sp.q)+' kg ('+ets.length+' etq.)'});
      });
    }
    add('Soma das etiquetas difere do saldo da vaga','media',i7);
    /* I10: movimentos malformados no log recente */
    var i10=[];
    try{(MV||[]).slice(0,500).forEach(function(m){
      if(!m)return;
      if(!(Number(m.q)>0))i10.push({ref:(m.pr||'?')+' @ '+(m.code||m.at||''),det:'movimento com quantidade inválida ('+m.q+')'});
      else if(!m.pr)i10.push({ref:m.code||m.at||'?',det:'movimento sem produto'});
    });}catch(e){}
    add('Movimentos malformados (últimos 500)','baixa',i10.slice(0,50));
    return problemas;
  }
  window.saudeVerificar=verificar;

  /* ===== CORREÇÃO AUTOMÁTICA (só o que é seguro decidir sozinho) =====
     · etiqueta → vaga inexistente/vazia: solta a etiqueta (ela não está na prateleira;
       se estiver no Chão 70, continua lá — o chão não usa LOC)
     · armazenada mas no intermediário: sai do intermediário (a prateleira é a verdade)
     · prateleira + Chão 70 ao mesmo tempo: sai do chão (regra da casa: entrou na
       prateleira, saiu do chão)
     O que exige OLHO HUMANO fica de fora de propósito: produto divergente, soma que
     não bate e saldo negativo são sintoma de contagem — corrige recontando a vaga
     no Inventário, não com um botão. */
  window.saudeCorrigir=function(){
    var n1=0,n2=0,n3=0;
    try{
      var byCode={};(S||[]).forEach(function(x){try{byCode[code(x)]=x;}catch(e){}});
      if(typeof LOC!=='undefined'){
        Object.keys(LOC).slice().forEach(function(et){
          var sp=byCode[LOC[et]];
          if(!sp||!sp.o||(Number(sp.q)||0)<=0){
            delete LOC[et];if(typeof BOB!=='undefined'&&BOB[et])BOB[et].rem=0;
            try{if(typeof syncDelLoc==='function')syncDelLoc(et);}catch(e){}
            n1++;return;
          }
          try{if(typeof STAGE!=='undefined'&&STAGE.some(function(x){return x.et===et;})){
            STAGE=STAGE.filter(function(x){return x.et!==et;});
            try{if(typeof syncDelStage==='function')syncDelStage(et);}catch(e){}
            n2++;
          }}catch(e){}
          try{if(typeof window.f70HasEt==='function'&&window.f70HasEt(et)&&typeof window.f70Saida==='function'){
            window.f70Saida(et);n3++;
          }}catch(e){}
        });
        try{saveLOC();}catch(e){}
        try{if(typeof saveStage==='function')saveStage();}catch(e){}
        try{if(typeof updateStageBadge==='function')updateStageBadge();}catch(e){}
        try{persist();}catch(e){}
      }
    }catch(e){}
    try{toast('Corrigido: '+n1+' etiqueta(s) solta(s), '+n2+' fora do intermediário, '+n3+' fora do Chão 70');}catch(e){}
    return n1+n2+n3;
  };

  var GRAV={alta:{c:'#dc2626',t:'Crítico'},media:{c:'#d97706',t:'Atenção'},baixa:{c:'#6b7280',t:'Info'}};
  function render(){
    var v=document.getElementById('v-saude');if(!v)return;
    var probs=verificar();
    var tot=probs.reduce(function(a,p){return a+p.itens.length;},0);
    var head='<div class="ph-head"><div><p class="eb">Diagnóstico · dados reais</p><h1>Saúde do sistema</h1></div>'+
      '<div style="display:flex;gap:10px"><button class="btn brand" id="sdFix" style="padding:8px 16px">Corrigir automaticamente</button><button class="gbtn" id="sdRefresh" style="padding:8px 16px">Verificar de novo</button></div></div>'+
      '<div style="background:var(--card);border:1px solid var(--line);border-left:5px solid '+(tot?'#dc2626':'#15803d')+';border-radius:14px;padding:16px 20px;margin-bottom:18px">'+
        (tot?('<b style="color:#dc2626;font-size:1.05rem">'+tot+' inconsistência(s) encontrada(s)</b><div style="font-size:.82rem;color:var(--muted);margin-top:4px">Cada uma é algo que não deveria existir num armazém saudável — normalmente sintoma de sync entre aparelhos ou operação fora do fluxo. Corrija pelo Inventário (recontar a vaga) ou pelo Estoque.</div>')
            :('<b style="color:#15803d;font-size:1.05rem">Tudo coerente.</b><div style="font-size:.82rem;color:var(--muted);margin-top:4px">Etiquetas, vagas, saldos e log de movimentos passaram em todas as verificações.</div>'))+
      '</div>';
    var corpo=probs.map(function(p){
      var g=GRAV[p.grav]||GRAV.baixa;
      return '<div style="background:var(--card);border:1px solid var(--line);border-radius:14px;margin-bottom:12px;overflow:hidden">'+
        '<div style="padding:12px 18px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;gap:10px">'+
          '<b style="font-size:.9rem">'+p.regra+'</b>'+
          '<span style="background:'+g.c+'1a;color:'+g.c+';border-radius:99px;padding:2px 12px;font-size:.72rem;font-weight:800">'+g.t+' · '+p.itens.length+'</span></div>'+
        '<div style="padding:6px 18px 12px">'+p.itens.slice(0,20).map(function(it){
          return '<div style="display:flex;gap:12px;padding:7px 0;border-bottom:1px dashed var(--line);font-size:.82rem"><b class="mono" style="flex:none;min-width:110px">'+it.ref+'</b><span style="color:var(--muted)">'+it.det+'</span></div>';
        }).join('')+(p.itens.length>20?'<div style="padding:8px 0;font-size:.74rem;color:var(--muted)">+'+(p.itens.length-20)+' — use o Exportar</div>':'')+'</div></div>';
    }).join('');
    var exp=tot?'<button class="gbtn" id="sdExport" style="padding:8px 16px;margin-top:4px">Exportar CSV</button>':'';
    v.innerHTML=head+corpo+exp;
    var rf=document.getElementById('sdRefresh');if(rf)rf.onclick=render;
    var fx=document.getElementById('sdFix');if(fx)fx.onclick=function(){
      if(!confirm('Corrigir automaticamente?\n\n· Etiquetas apontando pra vaga inexistente/vazia serão SOLTAS (se estiverem no Chão 70, continuam lá)\n· Bobinas armazenadas saem do intermediário\n· Bobinas na prateleira saem do Chão 70\n\nProduto divergente, soma que não bate e saldo negativo NÃO são tocados — esses se corrigem recontando a vaga no Inventário.'))return;
      window.saudeCorrigir();render();
    };
    var ex=document.getElementById('sdExport');if(ex)ex.onclick=function(){
      var rows=[['Regra','Gravidade','Referencia','Detalhe']];
      verificar().forEach(function(p){p.itens.forEach(function(it){rows.push([p.regra,p.grav,it.ref,it.det]);});});
      try{dl('saude_sistema_'+new Date().toISOString().slice(0,10)+'.csv',csv(rows));toast('Diagnóstico exportado');}catch(e){}
    };
  }
  window.renderSaude=render;
  /* injeta a aba (admin) */
  try{
    var ref=[].slice.call(document.querySelectorAll('.nav')).find(function(n){return n.dataset.view==='v-amrp';})
        ||[].slice.call(document.querySelectorAll('.nav')).find(function(n){return n.dataset.view==='v-abc';});
    var nv=document.createElement('div');nv.className='nav adminOnly';nv.dataset.view='v-saude';
    nv.innerHTML='<span class="ni"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" width="20" height="20"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg></span>Monitoramento do Sistema';
    if(ref&&ref.parentNode)ref.after(nv);else{var sn=document.querySelector('.sb-nav');if(sn)sn.appendChild(nv);}
    nv.onclick=function(){go('v-saude');};
    var sec=document.createElement('section');sec.className='view';sec.id='v-saude';
    var mn=document.querySelector('main');if(mn)mn.appendChild(sec);
    if(typeof TITLES!=='undefined')TITLES['v-saude']='Monitoramento do Sistema';
  }catch(e){}
})();
/* roteador da Saúde (fora da IIFE p/ enxergar o render global) */
(function(){try{var _r=render;render=function(id){if(id==='v-saude')return window.renderSaude();return _r(id);};}catch(e){}})();

